<script setup lang="ts">import{onMounted}from'vue';import{storeToRefs}from'pinia';import ProcurementSubnav from'../components/ProcurementSubnav.vue';import ProcurementScenarioBar from'../components/ProcurementScenarioBar.vue';import{useProcurementStore}from'../runtime/procurement-store';import'./procurement-views.css';const store=useProcurementStore();const{workspace,scenario,actor,loading,error}=storeToRefs(store);onMounted(()=>store.load())</script>
<template><section class="procurement-page"><header class="procurement-header"><div><h1>直送供应统计</h1><p>供应商直送采购与退采执行统计。</p></div><ProcurementScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><ProcurementSubnav/><div class="procurement-toolbar"><label>出入库日期<input type="date" disabled></label><label class="grow">单号 / 采购单号 / 供应商 / 客户<input disabled placeholder="执行数据接入后可筛选"></label><button class="pur-button" disabled>查询</button></div><div class="procurement-summary"><article v-for="label in ['采购订单笔数','退单笔数','订单金额','退单金额','合计金额']" :key="label"><span>{{label}}</span><strong>不可用</strong></article></div><div v-if="error" class="procurement-state error">{{error}}</div><div v-else-if="loading" class="procurement-state">正在检查执行数据源…</div><div v-else class="procurement-state"><span class="pur-status unavailable">数据源未接入</span><strong>{{workspace.directDelivery.message}}</strong><p class="unavailable-note">本页不是空数据。只有 PUR-002/003 提供有效的直送采购入库、退采出库、客户快照与执行状态后，才能计算笔数与金额；当前不以 0 冒充统计结果。</p></div></section></template>
